            {formatBytes(state.recent.maxBytes)}.
          </p>
          {state.journal ? (
            <>
              <p>
                Journal bound: {state.journal.maxSegments} ×{' '}
                {formatBytes(state.journal.maxSegmentBytes)}, retained for{' '}
                {state.journal.retentionHours / 24} days.
              </p>
              <code>{state.journal.location}</code>
