        <span>
          {item.severity} · {item.state}
        </span>
      </div>
      <p>
        {item.owner === 'window-manager' ? 'Window manager' : 'React error boundary'} ·
        renderer {item.ownerId}, generation {item.ownerGeneration} · {item.count}{' '}
        occurrence
        {item.count === 1 ? '' : 's'}
      </p>
      <p>Classification: {item.classification.replaceAll('-', ' ')}</p>
      <p>
