  } catch {}
  if (!found) errors.push(`Env var not referenced in code: ${name}`)
}

const scenarioSource = readFileSync(join(repo, 'src/main/smoke/scenario-selection.mts'), 'utf8')
for (const m of readme.matchAll(/npm run smoke:scenario -- ([\w -]+?)\s*(?:#|$)/gm)) {
